"""
IHDP-based semi-synthetic binary-IV benchmark.

This benchmark keeps the standard IHDP semi-synthetic covariate base and
Hill-style treatment-response surfaces, then overlays a binary encouragement
design with noncompliance and known CATE:

* real covariates from the standard IHDP/NPCI benchmark
* binary instrument generated by the benchmark designer
* binary treatment with broad, learnable compliance heterogeneity
* continuous outcome with additive latent residual confounding and known CATE

The structural world (latent confounder, compliance threshold and outcome
noise) is fixed per IHDP row; experiment seeds only affect which rows are
sampled into the pool / target splits.  See Appendix B.3.3 of the paper.
"""

from __future__ import annotations

import os
from functools import lru_cache
from pathlib import Path
from typing import Dict, Tuple

import numpy as np
import pandas as pd

from src.library.datasets.data_class import TestDataSet
from src.library.datasets.propensity import marginal_logistic_probability


SCENARIO_NAME = "ihdp_iv_semisynth"
BINARY_DGP_SCENARIOS = [SCENARIO_NAME]
DEFAULT_D_COVARIATE = 25

_REPO_ROOT = Path(__file__).resolve().parents[3]
# Place the standard NPCI file at data/ihdp/ihdp_npci_1.csv, or point the
# IVIG_IHDP_CSV environment variable at it.
_DEFAULT_CSV_PATH = _REPO_ROOT / "data" / "ihdp" / "ihdp_npci_1.csv"

_STRUCTURAL_SEED = 20260401

_P0_INTERCEPT = -1.35
_P1_INTERCEPT = -0.85
_SCORE_X_WEIGHT = 0.35
_U_STAGE1_WEIGHT = 0.55
_Z1_BAND_BONUS = 0.55

_BAND_CENTER = 0.25
_BAND_WIDTH = 0.50
_REFINE_CENTER = 0.10
_REFINE_WIDTH = 0.42
_REFINE_LOGIT_WEIGHT = 1.20
_TAU_HILL_WEIGHT = 0.22
_TAU_SHARED_WEIGHT = 0.48
_TAU_REFINEMENT_WEIGHT = 0.42
_TAU_DETAIL_SCALE = 0.08
_TAU_REFINEMENT_DETAIL = 0.18
_U_OUTCOME_WEIGHT = 0.65
_SIGMA_Y = 1.0


def is_binary_scenario(scenario: str) -> bool:
    return scenario == SCENARIO_NAME


def get_default_d_covariate(scenario: str) -> int:
    return DEFAULT_D_COVARIATE


def _check_scenario(scenario: str) -> None:
    if scenario != SCENARIO_NAME:
        raise ValueError(f"Unknown semi-synthetic scenario '{scenario}'. Expected '{SCENARIO_NAME}'.")


def _validate_d_covariate(d_covariate: int | None) -> int:
    if d_covariate is None:
        return DEFAULT_D_COVARIATE
    if int(d_covariate) != DEFAULT_D_COVARIATE:
        raise ValueError(
            f"{SCENARIO_NAME} uses exactly {DEFAULT_D_COVARIATE} covariates; got d_covariate={d_covariate}."
        )
    return DEFAULT_D_COVARIATE


def _sigmoid(x: np.ndarray) -> np.ndarray:
    return 1.0 / (1.0 + np.exp(-x))


def resolve_data_path(csv_path=None) -> Path:
    """Resolve an explicit path, then the environment, then the repo default."""
    return Path(csv_path or os.environ.get("IVIG_IHDP_CSV") or _DEFAULT_CSV_PATH).expanduser().resolve()


def _load_ihdp_base(csv_path=None) -> Dict[str, np.ndarray]:
    return _load_ihdp_base_for_path(str(resolve_data_path(csv_path)))


@lru_cache(maxsize=4)
def _load_ihdp_base_for_path(csv_path: str) -> Dict[str, np.ndarray]:
    if not Path(csv_path).is_file():
        raise FileNotFoundError(
            f"IHDP benchmark file not found at '{csv_path}'. "
            "Download the standard NPCI file ihdp_npci_1.csv (see README) and place it at data/ihdp/, "
            "or set IVIG_IHDP_CSV to its location."
        )

    raw = pd.read_csv(csv_path, header=None).to_numpy(dtype=np.float32)
    if raw.ndim != 2 or raw.shape[0] == 0 or raw.shape[1] != 30 or not np.isfinite(raw).all():
        raise ValueError("IHDP CSV must have finite numeric values in 30 columns: t, y, y_cf, mu0, mu1, x1..x25.")
    x = raw[:, 5:].copy()
    # One IHDP binary column is encoded as {1, 2}; map it back to {0, 1}.
    col = x[:, 13]
    if np.all(np.isin(np.unique(col), [1.0, 2.0])):
        x[:, 13] = col - 1.0

    return {
        "row_id": np.arange(x.shape[0], dtype=np.int64),
        "x": x.astype(np.float32),
        "mu0": raw[:, 3].astype(np.float32),
        "mu1": raw[:, 4].astype(np.float32),
        "tau_hill": (raw[:, 4] - raw[:, 3]).astype(np.float32),
        "tau": _build_reference_cate(x, raw[:, 4] - raw[:, 3]),
    }


def _risk_score(x: np.ndarray) -> np.ndarray:
    return (
        0.45 * x[:, 0]
        + 0.30 * x[:, 1]
        + 0.20 * x[:, 2]
        + 0.15 * x[:, 5]
    ).astype(np.float32)


def _band_components(x: np.ndarray) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    s = _risk_score(x)
    band = np.exp(-((s - _BAND_CENTER) ** 2) / (2.0 * _BAND_WIDTH**2)).astype(np.float32)
    band_mean = float(band.mean())
    band_std = float(max(band.std(), 1e-6))
    band_z = ((band - band_mean) / band_std).astype(np.float32)
    return s.astype(np.float32), band.astype(np.float32), band_z.astype(np.float32)


def _refinement_components(x: np.ndarray, band: np.ndarray) -> Tuple[np.ndarray, np.ndarray]:
    refine_score = (
        0.85 * x[:, 0]
        - 0.60 * x[:, 1]
        + 0.45 * x[:, 2]
        + 0.30 * x[:, 5]
    ).astype(np.float32)
    refine_core = np.exp(
        -((refine_score - _REFINE_CENTER) ** 2) / (2.0 * _REFINE_WIDTH**2)
    ).astype(np.float32)
    refine_gate = _sigmoid(_REFINE_LOGIT_WEIGHT * (x[:, 2] - 0.10)).astype(np.float32)
    refinement = (band * refine_core * refine_gate).astype(np.float32)
    refinement_mean = float(refinement.mean())
    refinement_std = float(max(refinement.std(), 1e-6))
    refinement_z = ((refinement - refinement_mean) / refinement_std).astype(np.float32)
    return refinement, refinement_z


def _build_reference_cate(x: np.ndarray, tau_hill: np.ndarray) -> np.ndarray:
    """Construct fixed effects once using the complete reference population."""
    _, band, band_z = _band_components(x)
    refinement, refinement_z = _refinement_components(x, band)
    detail = np.tanh(0.8 * x[:, 0] - 0.5 * x[:, 1] + 0.4 * x[:, 2] + 0.3 * x[:, 5]).astype(np.float32)
    refine_detail = np.tanh(
        0.75 * x[:, 0] * x[:, 2]
        - 0.45 * x[:, 1]
        + 0.30 * x[:, 5]
    ).astype(np.float32)
    shared = (
        0.75 * band_z
        - 0.45 * x[:, 5]
        + 0.20 * x[:, 13]
        + 0.15 * np.tanh(x[:, 0] * x[:, 2])
    ).astype(np.float32)
    shared_z = ((shared - float(shared.mean())) / max(float(shared.std()), 1e-6)).astype(np.float32)
    hill_centered = (tau_hill - float(tau_hill.mean())).astype(np.float32)
    tau_base = (
        float(tau_hill.mean())
        + _TAU_HILL_WEIGHT * hill_centered
        + _TAU_SHARED_WEIGHT * shared_z
        + _TAU_DETAIL_SCALE * band * detail
        + _TAU_REFINEMENT_WEIGHT * refinement_z
        + _TAU_REFINEMENT_DETAIL * refinement * refine_detail
    )
    return tau_base.astype(np.float32)


def _get_structural_world(csv_path=None) -> Dict[str, np.ndarray]:
    return _get_structural_world_for_path(str(resolve_data_path(csv_path)))


@lru_cache(maxsize=4)
def _get_structural_world_for_path(csv_path: str) -> Dict[str, np.ndarray]:
    base = _load_ihdp_base(csv_path)
    n_rows = int(base["x"].shape[0])
    rng = np.random.RandomState(_STRUCTURAL_SEED)
    return {
        "u": rng.randn(n_rows).astype(np.float32),
        "latent_threshold": rng.uniform(size=n_rows).astype(np.float32),
        "eps": rng.randn(n_rows).astype(np.float32),
    }


def _sample_active_pool_indices(
    n_pool: int,
    n_target: int,
    rng: np.random.RandomState,
    csv_path=None,
) -> Tuple[np.ndarray, np.ndarray]:
    base = _load_ihdp_base(csv_path)
    n_rows = int(base["x"].shape[0])
    perm = rng.permutation(n_rows)

    if int(n_pool) >= n_rows:
        pool_idx = perm
        target_idx = rng.choice(n_rows, size=n_target, replace=n_target > n_rows)
        return pool_idx.astype(np.int64), target_idx.astype(np.int64)

    pool_idx = perm[: int(n_pool)]
    remaining = perm[int(n_pool) :]
    if n_target <= len(remaining):
        target_idx = remaining[:n_target]
    else:
        target_idx = rng.choice(n_rows, size=n_target, replace=n_target > n_rows)
    return pool_idx.astype(np.int64), target_idx.astype(np.int64)


def _generate_structural_potentials_for_indices(
    row_idx: np.ndarray,
    csv_path=None,
) -> Tuple[Dict[str, np.ndarray], Dict[str, np.ndarray]]:
    base = _load_ihdp_base(csv_path)
    structural = _get_structural_world(csv_path)

    row_idx = np.asarray(row_idx, dtype=np.int64).reshape(-1)
    x = base["x"][row_idx]
    mu0 = base["mu0"][row_idx]
    u = structural["u"][row_idx]
    latent_threshold = structural["latent_threshold"][row_idx]
    eps = structural["eps"][row_idx] * _SIGMA_Y

    score, band, _ = _band_components(x)
    p0 = _sigmoid(_P0_INTERCEPT + _SCORE_X_WEIGHT * score + _U_STAGE1_WEIGHT * u).astype(np.float32)
    p1 = _sigmoid(
        _P1_INTERCEPT
        + _SCORE_X_WEIGHT * score
        + _U_STAGE1_WEIGHT * u
        + _Z1_BAND_BONUS * band
    ).astype(np.float32)

    t0 = (latent_threshold < p0).astype(np.float32)
    t1 = (latent_threshold < p1).astype(np.float32)

    tau_base = base["tau"][row_idx]
    marginal_p0 = marginal_logistic_probability(_P0_INTERCEPT + _SCORE_X_WEIGHT * score, _U_STAGE1_WEIGHT)
    marginal_p1 = marginal_logistic_probability(
        _P1_INTERCEPT + _SCORE_X_WEIGHT * score + _Z1_BAND_BONUS * band, _U_STAGE1_WEIGHT,
    )
    # Keep the treatment effect purely covariate-dependent. The latent
    # confounder affects compliance and the additive outcome residual, but not
    # the treatment contrast; this preserves the conditional IV mean
    # decomposition used by GPIV.
    tau = tau_base.astype(np.float32)
    y0_cf = (mu0 + _U_OUTCOME_WEIGHT * u + eps).astype(np.float32)
    y1_cf = (y0_cf + tau).astype(np.float32)

    y_obs0 = np.where(t0 > 0.5, y1_cf, y0_cf).astype(np.float32)
    y_obs1 = np.where(t1 > 0.5, y1_cf, y0_cf).astype(np.float32)

    common = {
        "TAU": tau.reshape(-1, 1),
        "TAU_BASE": tau_base.reshape(-1, 1),
        "U": u.reshape(-1, 1),
    }
    z0_outcomes = {
        "T": t0.reshape(-1, 1),
        "Y": y_obs0.reshape(-1, 1),
        "P": marginal_p0.reshape(-1, 1).astype(np.float32),
        **common,
    }
    z1_outcomes = {
        "T": t1.reshape(-1, 1),
        "Y": y_obs1.reshape(-1, 1),
        "P": marginal_p1.reshape(-1, 1).astype(np.float32),
        **common,
    }
    return z0_outcomes, z1_outcomes


def generate_binary_pool(
    scenario: str,
    n_pool: int = 450,
    d_covariate: int = DEFAULT_D_COVARIATE,
    n_test: int = 200,
    seed: int | None = None,
    csv_path=None,
):
    _check_scenario(scenario)
    _validate_d_covariate(d_covariate)

    rng = np.random.RandomState(seed)
    csv_path = resolve_data_path(csv_path)
    base = _load_ihdp_base(csv_path)
    pool_idx, target_idx = _sample_active_pool_indices(n_pool, n_test, rng, csv_path)

    x_pool = base["x"][pool_idx].astype(np.float32)
    z0_outcomes, z1_outcomes = _generate_structural_potentials_for_indices(pool_idx, csv_path)

    x_test = base["x"][target_idx].astype(np.float32)
    test_tau = base["tau"][target_idx].reshape(-1, 1)
    test_data = TestDataSet(
        treatment=np.zeros((len(target_idx), 1), dtype=np.float32),
        covariate=x_test,
        structural=test_tau,
    )
    return x_pool, z0_outcomes, z1_outcomes, test_data
